#include <string>
#include <vector>
#include <cmath>

class Solution {
public:
    int mirrorFrequencyDistance(std::string s) {
        std::vector<int> counts(26, 0);
        for (char c : s) counts[c - 'a']++;
        int diff = 0;
        for (int i = 0; i < 26; ++i) {
            diff += std::abs(counts[i] - counts[25 - i]);
        }
        return diff / 2;
    }
};

class Solution {
    public int mirrorFrequencyDistance(String s) {
        int[] counts = new int[26];
        for (char c : s.toCharArray()) counts[c - 'a']++;
        int diff = 0;
        for (int i = 0; i < 26; i++) {
            diff += Math.abs(counts[i] - counts[25 - i]);
        }
        return diff / 2;
    }
}

